<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/csrf.php';require_role(['Principal']);
$user=current_user();$error=$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$requestId=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';$remarks=trim($_POST['remarks']??'');
 $rq=$pdo->prepare('SELECT cr.*,u.id student_user_id FROM clearance_requests cr JOIN students s ON s.id=cr.student_id JOIN users u ON u.id=s.user_id WHERE cr.id=?');$rq->execute([$requestId]);$request=$rq->fetch();
 $pending=$pdo->prepare('SELECT COUNT(*) FROM department_clearances WHERE request_id=? AND status!=\'Approved\'');$pending->execute([$requestId]);$pendingCount=(int)$pending->fetchColumn();
 $missingHod=$pdo->prepare('SELECT COUNT(*) FROM department_clearances dc WHERE dc.request_id=? AND dc.status=\'Approved\' AND NOT EXISTS(SELECT 1 FROM approvals a WHERE a.request_id=dc.request_id AND a.role=\'HOD\' AND a.department_id=dc.department_id AND a.status=\'Approved\')');$missingHod->execute([$requestId]);$missingCount=(int)$missingHod->fetchColumn();
 if(!$request||$request['status']==='Approved'||$request['status']==='Rejected'){$error='This request is not available for final approval.';}
 elseif(!in_array($action,['Approved','Rejected'],true)||($action==='Rejected'&&$remarks==='')){$error='A rejection reason is required.';}
 elseif($action==='Approved'&&($pendingCount>0||$missingCount>0)){$error='Final approval requires every department and HOD approval.';}
 else{try{$pdo->beginTransaction();
  $pdo->prepare('INSERT INTO approvals(request_id,approver_user_id,role,status,remarks) VALUES(?,?,?,?,?)')->execute([$requestId,$user['id'],'Principal',$action,$remarks]);
  if($action==='Rejected'){$pdo->prepare('UPDATE clearance_requests SET status=\'Rejected\',completed_at=NOW() WHERE id=?')->execute([$requestId]);notify($pdo,(int)$request['student_user_id'],'Final clearance rejected','The Principal rejected your No Due request. Reason: '.$remarks,base_url().'/student/clearance_status.php');}
  else{$pdo->prepare('UPDATE clearance_requests SET status=\'Approved\',completed_at=NOW() WHERE id=?')->execute([$requestId]);$cid=certificate_id();$protocol=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!='off'?'https':'http';$host=$_SERVER['HTTP_HOST']??'localhost';$verificationUrl=$protocol.'://'.$host.base_url().'/verification/verify_certificate.php?id='.rawurlencode($cid);$pdo->prepare('INSERT INTO certificates(request_id,student_id,certificate_id,issue_date,verification_url) VALUES(?,?,?,CURDATE(),?)')->execute([$requestId,$request['student_id'],$cid,$verificationUrl]);notify($pdo,(int)$request['student_user_id'],'No Due certificate generated','Final clearance has been approved and your certificate is ready.',base_url().'/student/certificate.php?id='.$requestId);}
  audit_log($pdo,(int)$user['id'],'Principal',$action.' final no-due clearance',$requestId,$remarks);$pdo->commit();$success='Final clearance '.($action==='Approved'?'approved':'rejected').' successfully.';
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Unable to complete final approval.';}}
}
$sql="SELECT cr.*,u.name student_name,s.usn FROM clearance_requests cr JOIN students s ON s.id=cr.student_id JOIN users u ON u.id=s.user_id WHERE cr.status!='Approved' AND cr.status!='Rejected' ORDER BY cr.submitted_at DESC";
$rows=$pdo->query($sql)->fetchAll();
$pageTitle='Final Approvals | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Principal</span></div><div class="avatar"><?=e(strtoupper(substr($user['name'],0,2)))?></div></header><div class="content"><div class="page-header"><div><p>FINAL AUTHORIZATION</p><h1>No Due Approvals</h1></div></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>USN</th><th>Semester</th><th>Department Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):$pending=$pdo->prepare('SELECT COUNT(*) FROM department_clearances WHERE request_id=? AND status!=\'Approved\'');$pending->execute([$r['id']]);$pendingCount=(int)$pending->fetchColumn();$missing=$pdo->prepare('SELECT COUNT(*) FROM department_clearances dc WHERE dc.request_id=? AND dc.status=\'Approved\' AND NOT EXISTS(SELECT 1 FROM approvals a WHERE a.request_id=dc.request_id AND a.role=\'HOD\' AND a.department_id=dc.department_id AND a.status=\'Approved\')');$missing->execute([$r['id']]);$missingCount=(int)$missing->fetchColumn();?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['usn'])?></td><td><?=e($r['semester'])?></td><td><b class="<?=($pendingCount||$missingCount)?'status pending':'status approved'?>"><?=$pendingCount?'Departments pending':($missingCount?'HOD approvals pending':'Ready')?></b></td><td><details><summary class="action-btn">Review</summary><form method="post" class="inline-form" style="display:grid;margin-top:8px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><textarea name="remarks" placeholder="Remarks (required for rejection)"></textarea><select name="action"><option value="Approved">Approve</option><option value="Rejected">Reject</option></select><button class="action-btn approve" type="submit">Submit</button></form></details></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No requests awaiting final approval.</td></tr><?php endif;?></tbody></table></div></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
